def name(op):
    if op in T: return T[op]
    if op & 0xf800 == 0xa800:
        b=op & ~0x0400
        if b in T: return T[b]+'(autopop)'
        return None
    n=op & 0xff
    if n==0xad: return 'Gestalt'
    if n==0x90: return 'SysEnvirons'
    if n < len(OS) and OS[n]!='-': return OS[n]+('' if not op&0x600 else ('.%s'%('sys' if op&0x400 else '')+('clear' if op&0x200 else '')))
    return None
